import { useState } from 'react';
import styles from './TransactionForm.module.css';

const TransactionForm = ({ onAddTransaction, currentBalance, setCurrentBalance }) => {
  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    type: 'income', // Por defecto es 'income'
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Validar que el monto sea un número positivo
    const amount = parseFloat(formData.amount);
    if (isNaN(amount) || amount <= 0) {
      alert('Por favor ingrese un monto válido mayor a cero');
      return;
    }

    // Obtener la fecha y hora actual
    const now = new Date();
    const dayOfWeek = now.toLocaleDateString('es-ES', { weekday: 'long' });
    const time = now.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
    const date = now.toISOString().split('T')[0]; // Fecha en formato YYYY-MM-DD

    // Crear la transacción
    const transaction = {
      ...formData,
      amount: amount,
      day: dayOfWeek,
      time: time,
      date: date
    };

    // Actualizar el saldo actual antes de enviar la transacción
    const balanceUpdate = formData.type === 'income' ? amount : -amount;
    setCurrentBalance(prevBalance => {
      const newBalance = prevBalance + balanceUpdate;
      
      // Validar que no quede saldo negativo (opcional)
      if (newBalance < 0) {
        alert('No puede realizar esta transacción: saldo insuficiente');
        return prevBalance; // Mantener el saldo anterior
      }
      
      return newBalance;
    });

    // Enviar la transacción al Dashboard
    onAddTransaction(transaction);
    
    // Resetear el formulario
    setFormData({
      description: '',
      amount: '',
      type: 'income',
    });
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit}>
      <div className={styles.balanceDisplay}>
        Saldo Actual: ${currentBalance.toFixed(2)}
      </div>
      
      <input
        type="text"
        name="description"
        placeholder="Descripción"
        value={formData.description}
        onChange={handleChange}
        required
        className={styles.input}
      />
      <input
        type="number"
        name="amount"
        placeholder="Monto"
        value={formData.amount}
        onChange={handleChange}
        min="0.01"
        step="0.01"
        required
        className={styles.input}
      />
      <select 
        name="type" 
        value={formData.type} 
        onChange={handleChange}
        className={styles.select}
      >
        <option value="income">Ingreso</option>
        <option value="expense">Gasto</option>
      </select>
      <button type="submit" className={styles.button}>
        {formData.type === 'income' ? 'Agregar Ingreso' : 'Agregar Gasto'}
      </button>
    </form>
  );
};

export default TransactionForm;
